<?php $item=$item??[];$kind=$kind??'article';$edit=!empty($isEdit);$postKind=$kind==='faq'?'faqs':($kind==='page'?'pages':'articles');$action=admin_url('cms/'.$postKind.($edit?'/'.(int)$item['id'].'/edit':'')); ?>
<section class="admin-panel admin-form-panel"><div class="admin-panel-heading"><div><span class="admin-eyebrow"><?= $edit?'EDIT CONTENT':'NEW CONTENT' ?></span><h2><?= e(ucfirst($kind)) ?> details</h2></div><a class="admin-button" href="<?= e(admin_url('cms/'.$postKind)) ?>">Back to list</a></div>
<form method="post" action="<?= e($action) ?>"><?= admin_csrf_field() ?><?php if($edit): ?><input type="hidden" name="version" value="<?= (int)$item['version'] ?>"><?php endif; ?>
<div class="admin-form-grid">
<?php if($kind==='faq'): ?>
<label>Category<input name="category" maxlength="100" required value="<?= e($item['category']??'') ?>"></label><label>Display order<input type="number" name="display_order" min="0" max="65535" value="<?= e((string)($item['display_order']??0)) ?>"></label><label class="admin-field-wide">Question<input name="question" maxlength="500" required value="<?= e($item['question']??'') ?>"></label><label class="admin-field-wide">Answer<textarea name="answer" rows="7" maxlength="5000" required><?= e($item['answer']??'') ?></textarea></label>
<?php else: ?>
<label>Title<input name="title" maxlength="<?= $kind==='article'?'220':'200' ?>" required value="<?= e($item['title']??'') ?>"></label><label>URL slug<input name="slug" maxlength="<?= $kind==='article'?'240':'220' ?>" required value="<?= e($item['slug']??'') ?>"><small>Public route will use this slug.</small></label>
<?php if($kind==='article'): ?><label>Category<select name="category_id" required><?php foreach($categories as $category): ?><option value="<?= (int)$category['id'] ?>" <?= (int)($item['category_id']??0)===(int)$category['id']?'selected':'' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></label><label>Featured image path<input name="featured_image" maxlength="255" value="<?= e($item['featured_image']??'') ?>" placeholder="uploads/cms/…"><small><a href="<?= e(admin_url('cms/media')) ?>">Upload or manage CMS images</a></small></label><label>Image alt text<input name="image_alt" maxlength="255" value="<?= e($item['image_alt']??'') ?>"></label><label class="admin-field-wide">Excerpt<textarea name="excerpt" rows="3" maxlength="2000"><?= e($item['excerpt']??'') ?></textarea></label><?php endif; ?>
<label class="admin-field-wide">Content<textarea name="content" rows="16" maxlength="100000" required><?= e($item['content']??'') ?></textarea><small>Safe HTML formatting is allowed: paragraphs, headings, lists, emphasis and links. Scripts, embeds and event attributes are removed.</small></label>
<label>SEO title<input name="seo_title" maxlength="220" value="<?= e($item['seo_title']??'') ?>"></label><label>Meta description<input name="meta_description" maxlength="320" value="<?= e($item['meta_description']??'') ?>"></label>
<?php endif; ?>
<label>Publishing status<select name="status"><?php foreach(['draft','published','archived'] as $status): ?><option value="<?= e($status) ?>" <?= ($item['status']??'draft')===$status?'selected':'' ?>><?= e(ucfirst($status)) ?></option><?php endforeach; ?></select></label><?php if($kind!=='faq'): ?><label>Publish date and time<input type="datetime-local" name="published_at" value="<?= !empty($item['published_at'])?e(date('Y-m-d\TH:i',strtotime($item['published_at']))):'' ?>"><small>Use a future time to schedule publication.</small></label><?php endif; ?>
</div><div class="admin-form-actions"><button class="admin-button admin-button-primary" type="submit">Save <?= e(ucfirst($kind)) ?></button><a class="admin-button" href="<?= e(admin_url('cms/'.$postKind)) ?>">Cancel</a></div></form></section>
